<?php $pageTitle='Product Catalog'; require 'includes/header.php';
$q=trim($_GET['q']??''); $cat=(int)($_GET['cat']??0); $page=max(1,(int)($_GET['page']??1)); $limit=8; $offset=($page-1)*$limit;
$where=['p.is_archived=0']; $params=[]; if($q){$where[]='p.name LIKE ?';$params[]="%$q%";} if($cat){$where[]='p.category_id=?';$params[]=$cat;} $whereSql='WHERE '.implode(' AND ',$where);
$count=$pdo->prepare("SELECT COUNT(*) FROM products p $whereSql");$count->execute($params);$total=(int)$count->fetchColumn();
$stmt=$pdo->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id $whereSql ORDER BY p.name LIMIT $limit OFFSET $offset");$stmt->execute($params);$products=$stmt->fetchAll(); $cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll(); ?>
<section class="promo-strip py-5"><div class="container"><h1 class="display-4 fw-bold">Printing Product Catalog</h1><p class="lead mb-0">Choose a product, upload your file, and submit your custom print order.</p></div></section>
<main class="section-pad"><div class="container"><form class="row g-2 mb-4"><div class="col-md-6"><input name="q" value="<?= e($q) ?>" class="form-control" placeholder="Search products"></div><div class="col-md-4"><select name="cat" class="form-select"><option value="0">All categories</option><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= $cat==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-red w-100">Filter</button></div></form><div class="row g-4">
<?php foreach($products as $p): ?><div class="col-sm-6 col-lg-3"><div class="card product-card h-100"><img src="<?= e($p['image'] ?: 'assets/images/product-placeholder.svg') ?>" class="product-img" alt="<?= e($p['name']) ?>"><div class="card-body d-flex flex-column"><span class="badge badge-brand align-self-start mb-2"><?= e($p['category_name']) ?></span><h5 class="fw-bold"><?= e($p['name']) ?></h5><p class="small text-muted flex-grow-1"><?= e($p['description']) ?></p><p class="mb-1"><b><?= money($p['price']) ?></b></p><p class="small">Stock: <?= (int)$p['stock'] ?></p><a href="product.php?id=<?= $p['id'] ?>" class="btn btn-red w-100">View and Customize</a></div></div></div><?php endforeach; ?>
</div><nav class="mt-4"><ul class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++): ?><li class="page-item <?= $i==$page?'active':'' ?>"><a class="page-link" href="?q=<?= urlencode($q) ?>&cat=<?= $cat ?>&page=<?= $i ?>"><?= $i ?></a></li><?php endfor; ?></ul></nav></div></main><?php require 'includes/footer.php'; ?>